// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { addProductToCart } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8080");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(`${baseUrl}/product/OLJCESPC7Z`);
    await addProductToCart(page);
    await expect(page.getByTestId("cart-heading")).toContainText("Cart (1)");

    // Everything below the item list must still render once the cart holds an item:
    // the shipping row, the Total row, and the checkout form's Place Order button.
    await expect(page.locator(".cart-summary-shipping-row")).toBeVisible();
    await expect(page.locator(".cart-summary-total-row")).toBeVisible();
    await expect(page.getByTestId("place-order-btn")).toContainText("Place Order");

    // A single $19.99 Sunglasses plus the quoted shipping must add up to the Total row.
    const shipping = parseFloat(
        (await page.locator(".cart-summary-shipping-row .text-right").innerText()).replace(/[^0-9.]/g, ""),
    );
    await expect(page.locator(".cart-summary-total-row .text-right"))
        .toHaveText(`$${(19.99 + shipping).toFixed(2)}`);
});
